function boxFaces(x,y,z,w,h,d,color){return cubeFaces(x,y,z,w,h,d,color)}
function coneFaces(x,y,z,r,h,color){let out=[],n=5,base=[];for(let i=0;i<n;i++){let a=i*6.283/n;base.push({x:x+Math.cos(a)*r,y,z:z+Math.sin(a)*r})}let tip={x:x+.18,y:y+h,z:z-.12};for(let i=0;i<n;i++)out.push(triangle(base[i],base[(i+1)%n],tip,shade(color,.74+i*.1)));return out}
function personFaces(x,z,angle,kind,phase=0){let out=[];let bob=Math.sin(phase)*.07, skin=kind==='zombie'?'#87947a':'#d3aa88',shirt=kind==='mara'?'#52675a':kind==='eli'?'#9b7955':'#68795f';let dx=Math.sin(angle)*.2,dz=-Math.cos(angle)*.2;
// hips and coat, head, legs, and compact arms make readable low-poly characters.
out.push(...boxFaces(x,bob+.55,z,.66,.82,.4,shirt));out.push(...boxFaces(x,bob+1.14,z,.42,.42,.42,skin));out.push(...boxFaces(x-dx,bob+.18,z-dz,.22,.38,.24,'#353b34'),...boxFaces(x+dx,bob+.18,z+dz,.22,.38,.24,'#353b34'));
out.push(...boxFaces(x+Math.cos(angle)*.35,bob+.65,z+Math.sin(angle)*.35,.2,.52,.2,shirt),...boxFaces(x-Math.cos(angle)*.35,bob+.65,z-Math.sin(angle)*.35,.2,.52,.2,shirt));
if(kind==='mara'){out.push(...boxFaces(x,bob+1.42,z,.42,.11,.44,'#4e3930'));out.push(...boxFaces(x+Math.sin(angle)*.48,bob+.73,z-Math.cos(angle)*.48,.18,.12,.48,'#292d2a'))}if(kind==='zombie')out.push(...boxFaces(x+.12,bob+1.2,z,.05,.07,.04,'#b34c3f'));
return out}
function drawPoly(pts,color){let projected=pts.map(p=>project(p,activeCam));if(projected.some(p=>!p))return;ctx.beginPath();ctx.moveTo(projected[0].x,projected[0].y);for(let i=1;i<projected.length;i++)ctx.lineTo(projected[i].x,projected[i].y);ctx.closePath();ctx.fillStyle=color;ctx.fill();ctx.strokeStyle='rgba(15,20,16,.22)';ctx.lineWidth=.7;ctx.stroke()}
let activeCam;
function render(){ctx.clearRect(0,0,W,H);let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#7b8b83');sky.addColorStop(.48,'#b7b49b');sky.addColorStop(1,'#686d58');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);let horizon=H*.37;ctx.fillStyle='#747862';ctx.fillRect(0,horizon,W,H-horizon);activeCam=cam();let faces=[];
// Roads, sidewalks, and weathered concrete slabs.
faces.push({pts:[{x:-7,y:-.04,z:-100},{x:7,y:-.04,z:-100},{x:7,y:-.04,z:30},{x:-7,y:-.04,z:30}],color:'#4c5049'});
faces.push({pts:[{x:-12,y:-.02,z:-100},{x:-7,y:-.02,z:-100},{x:-7,y:-.02,z:30},{x:-12,y:-.02,z:30}],color:'#827f70'},{pts:[{x:7,y:-.02,z:-100},{x:12,y:-.02,z:-100},{x:12,y:-.02,z:30},{x:7,y:-.02,z:30}],color:'#827f70'});
for(let z=-90;z<30;z+=8){faces.push({pts:[{x:-.12,y:.005,z},{x:.12,y:.005,z},{x:.12,y:.005,z+3.4},{x:-.12,y:.005,z+3.4}],color:'#b2a57d'})}
for(let x=-35;x<=35;x+=10)for(let z=-90;z<=30;z+=10){if(Math.abs(x)<12)continue;faces.push({pts:[{x:x-4.8,y:-.01,z:z-4.8},{x:x+4.8,y:-.01,z:z-4.8},{x:x+4.8,y:-.01,z:z+4.8},{x:x-4.8,y:-.01,z:z+4.8}],color:(x+z)%20?'#717265':'#747568'})}
// Tower in the distance.
for(let o of world){if(o.type==='building'){faces.push(...cubeFaces(o.x,0,o.z,o.w,o.h,o.d,o.color)); // dark boarded windows
for(let k=-1;k<=1;k+=2)faces.push(...boxFaces(o.x+k*o.w*.24,o.h*.54,o.z-o.d/2-.025,.36,.48,.04,'#3f4942'));
}else if(o.type==='car'){faces.push(...boxFaces(o.x,.1,o.z,o.w,.62,o.d,o.color),...boxFaces(o.x,.68,o.z,o.w*.8,.45,o.d*.52,'#4b5651'));for(let k of [-1,1])for(let q of [-1,1])faces.push(...boxFaces(o.x+k*o.w*.42,.16,o.z+q*o.d*.31,.18,.28,.45,'#292d2a'))}
else if(o.type==='tree'){faces.push(...boxFaces(o.x,.0,o.z,.3,o.h*.47,.3,'#574d3d'),...coneFaces(o.x,.7,o.z,.95,o.h*.58,'#52634d'),...coneFaces(o.x+0.12,1.35,o.z,.64,o.h*.52,'#647253'))}
else if(o.type==='tower'){faces.push(...boxFaces(o.x,0,o.z,.38,11,.38,'#555d56'),...boxFaces(o.x,10.8,o.z,3.8,.22,3.8,'#777c70'),...boxFaces(o.x,13.2,o.z,.15,4,.15,'#a4a28b'));faces.push(...boxFaces(o.x,13.2,o.z,1.2,.12,.12,'#b78956'))}}
// Ground debris: stones and wreckage. Deterministic placements.
for(let n=0;n<27;n++){let x=Math.sin(n*17.3)*10,z=-n*3.4+3;if(Math.abs(x)>7)faces.push(...boxFaces(x,.12,z,.32,.18,.22,n%3?'#77766a':'#8c7961'))}
// Living characters and infected.
let p=state.player;faces.push(...personFaces(state.partner.x,state.partner.z,Math.atan2(p.x-state.partner.x,-(p.z-state.partner.z)),'eli',state.walk-1));
for(let z of zombies)if(z.alive){faces.push(...personFaces(z.x,z.z,z.angle,'zombie',state.time*3));}
faces.push(...personFaces(p.x,p.z,p.angle,'mara',state.walk));
// Back-to-front painter sort by the center distance from camera.
faces.sort((a,b)=>{let avg=f=>f.pts.reduce((s,p)=>s+Math.hypot(p.x-activeCam.x,p.z-activeCam.z),0)/f.pts.length;return avg(b)-avg(a)});
for(let f of faces)drawPoly(f.pts,f.color);
// Crosshair target hint; shot flash.
if(state.flash>0){ctx.fillStyle=`rgba(255,215,145,${state.flash*.34})`;ctx.beginPath();ctx.arc(W/2,H*.43,42*state.flash,0,Math.PI*2);ctx.fill()}
// Atmospheric sun haze.
let haze=ctx.createRadialGradient(W*.75,H*.22,3,W*.75,H*.22,Math.min(W,H)*.38);haze.addColorStop(0,'rgba(226,202,151,.14)');haze.addColorStop(1,'rgba(226,202,151,0)');ctx.fillStyle=haze;ctx.fillRect(0,0,W,H);
}

