input.newString:
// Atmospheric sun haze.
let haze=ctx.createRadialGradient(W*.75,H*.22,3,W*.75,H*.22,Math.min(W,H)*.38);haze.addColorStop(0,'rgba(226,202,151,.14)');haze.addColorStop(1,'rgba(226,202,151,0)');ctx.fillStyle=haze;ctx.fillRect(0,0,W,H);
}
function reload(){let w=weapons[state.weapon];if(state.reload>0||state.ammo===w.mag||state.reserve===0)return;state.reload=1.05;toast('RELOADING…')}
function switchWeapon(n){state.weapon=(n+weapons.length)%weapons.length;let w=weapons[state.weapon];state.ammo=Math.min(state.ammo,w.mag);state.reserve=w.reserve;document.getElementById('weaponname').textContent=w.name;document.getElementById('ammo').textContent=state.ammo;document.getElementById('reserve').textContent=state.reserve}
function shoot(){if(!state.running||state.reload>0||state.fireCd>0)return;if(state.ammo<=0){toast('EMPTY — PRESS R TO RELOAD');state.fireCd=.4;return}let w=weapons[state.weapon];state.ammo--;state.fireCd=w.rate;state.flash=1;let p=state.player;if(pointer.down&&!pointer.touch){p.angle+=clamp((pointer.x-W/2)/W,-.45,.45)*.55}
let target=null,best=Infinity;for(let z of zombies){if(!z.alive)continue;let dx=z.x-p.x,dz=z.z-p.z,d=Math.hypot(dx,dz),a=Math.atan2(dx,-dz),delta=Math.atan2(Math.sin(a-p.angle),Math.cos(a-p.angle));let tolerance=state.weapon===2?.24:.12;if(d<20&&Math.abs(delta)<tolerance&&d<best){best=d;target=z}}
if(target){target.hp-=w.damage;if(target.hp<=0){target.alive=false;state.kills++;document.getElementById('kills').textContent=String(state.kills).padStart(2,'0');if(state.kills%3===0){state.reserve+=6;document.getElementById('reserve').textContent=state.reserve;toast('INFECTED DOWN · +6 AMMO')}}else target.hit=.16}
document.getElementById('ammo').textContent=state.ammo;if(state.ammo===0)reload()}
function update(dt){if(!state.running)return;state.time+=dt;state.fireCd=Math.max(0,state.fireCd-dt);state.flash=Math.max(0,state.flash-dt*4);if(state.toastTimer>0&&(state.toastTimer-=dt)<=0)document.getElementById('toast').classList.remove('show');if(state.reload>0){state.reload-=dt;if(state.reload<=0){let w=weapons[state.weapon],n=Math.min(w.mag-state.ammo,state.reserve);state.ammo+=n;state.reserve-=n;document.getElementById('ammo').textContent=state.ammo;document.getElementById('reserve').textContent=state.reserve}}
let p=state.player,mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,my=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y;if(keys.q)p.angle-=dt*1.8;if(keys.e)p.angle+=dt*1.8;let len=Math.hypot(mx,my);if(len>1){mx/=len;my/=len}if(len>.05){let fx=Math.sin(p.angle),fz=-Math.cos(p.angle),rx=Math.cos(p.angle),rz=Math.sin(p.angle);let speed=4.2;p.x+=((rx*mx+fx*(-my))*speed*dt);p.z+=((rz*mx+fz*(-my))*speed*dt);p.x=clamp(p.x,-16,16);p.z=clamp(p.z,-80,15);state.walk+=dt*9}
// Eli keeps close, pausing just behind Mara.
let ep=state.partner,ex=p.x-Math.sin(p.angle)*1.5,ez=p.z+Math.cos(p.angle)*1.5,ed=Math.hypot(ex-ep.x,ez-ep.z);if(ed>.6){ep.x+=(ex-ep.x)*Math.min(1,dt*2);ep.z+=(ez-ep.z)*Math.min(1,dt*2)}
for(let z of zombies){if(!z.alive)continue;let d=dist(z,p);if(d<17){let a=Math.atan2(p.x-z.x,-(p.z-z.z));z.angle=a;if(d>1.45){z.x+=Math.sin(a)*z.speed*dt;z.z-=Math.cos(a)*z.speed*dt}else{z.attack-=dt;if(z.attack<=0){state.health-=7;z.attack=1.2;document.getElementById('healthbar').style.width=state.health+'%';if(state.health<=0){state.health=0;finish(false)}}}}else{z.angle+=Math.sin(state.time+z.x)*dt*.15}}
if(pointer.down)shoot();if(p.z<-72&&!state.ended)finish(true);
}
function finish(win){state.ended=true;state.running=false;document.getElementById('endingtext').textContent=win?'The tower answers. Somewhere, beyond the dead city, someone heard you. Mara and Eli keep walking. Together.':'Mara falls, but Eli keeps the radio and runs. The city still has its secrets.';document.getElementById('ending').classList.remove('hide')}
function loop(now){let dt=Math.min(.04,(now-(loop.last||now))/1000);loop.last=now;update(dt);render();requestAnimationFrame(loop)}requestAnimationFrame(loop);

